import { withCacheTransaction } from './cache-transaction';
import type RemoteStorage from './remotestorage';
import type { RSItem, RSNode, RSNodes } from './interfaces/rs_node';
import type { QueuedRequestResponse } from './interfaces/queued_request_response';
import type { RemoteResponse } from './remote';
import config from './config';
import Env from './env';
import EventHandling from './eventhandling';
import log from './log';
import Authorize from './authorize';
import SyncError from './sync-error';
import UnauthorizedError from './unauthorized-error';
import { equalContentTypes } from './content-type';
import { acquireWriteLease, type WriteLease } from './write-lease';
import {
  applyMixins,
  deepClone,
  equal,
  globalContext,
  isFolder,
  isDocument,
  pathsFromRoot
} from './util';

let setupSync, syncOnConnect;

interface ResponseStatus {
  statusCode: string | number;
  successful: boolean | undefined;
  conflict: boolean | undefined;
  unAuth: boolean | undefined;
  notFound: boolean | undefined;
  changed: boolean | undefined;
  networkProblems: boolean | undefined;
}

interface SyncTask {
  action: "get" | "put" | "delete";
  path: string;
  promise: Promise<RemoteResponse>;
  operationId?: string;
  recovering?: boolean;
  releaseLease?: () => void;
}

let operationSequence = 0;
function nextOperationId(): string {
  return globalContext.crypto?.randomUUID?.() || Date.now().toString(36) + '-' + (++operationSequence) + '-' + Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
}

function taskFor (action: SyncTask["action"], path: SyncTask["path"], promise: SyncTask["promise"]): SyncTask {
  // Observe the response promise at creation time, so a task that is abandoned
  // before `finishTask()` awaits it (e.g. after `disconnect()`) cannot produce
  // an unhandled rejection. `finishTask()` still surfaces the failure to
  // queued callers through its own `try`/`catch`.
  promise.catch(() => {
    // Intentionally empty: only here to mark the rejection as observed.
  });
  return { action, path, promise };
}

const SESSION_ENDED_MESSAGE = 'Sync session ended before the request could be fulfilled.';

/**
 * Thrown when a task belonging to a `Sync` instance that is no longer the
 * active one (e.g. after `disconnect()`) would otherwise continue processing
 * its response. Callers abort before any cache write or change event can reach
 * the replacement session.
 */
class SessionEndedError extends Error {
  constructor () {
    super(SESSION_ENDED_MESSAGE);
    this.name = 'SessionEndedError';
  }
}

function nodeChanged (node: RSNode, etag: string): boolean {
  return node.common.revision !== etag &&
         (!node.remote || node.remote.revision !== etag);
}

function isStaleChild (node: RSNode): boolean {
  return !!node.remote && !!node.remote.revision &&
         !node.remote.itemsMap && node.remote.body === undefined;
}

function hasCommonRevision (node: RSNode): boolean {
  return !!node.common && !!node.common.revision;
}

function hasNoRemoteChanges (node: RSNode): boolean {
  if (node.remote && node.remote.revision && node.common.revision &&
      node.remote.revision !== node.common.revision) {
    return false;
  }
  return (node.common.body === undefined && node.remote.body === false) ||
         // A nonempty, unfetched revision has no body. Two unknown bodies are
         // not evidence of equality: keep that marker for the next fetch.
         ((!node.remote.revision || node.remote.body !== undefined) && equal(node.remote.body, node.common.body) &&
          equalContentTypes(node.remote.contentType, node.common.contentType));
}

function mergeMutualDeletion (node: RSNode): RSNode {
  if (node.remote && node.remote.body === false &&
      node.local && node.local.body === false) {
    delete node.local;
  }
  return node;
}

function handleVisibility (env, rs): void {
  function handleChange (isForeground): void {
    const oldValue = rs.getCurrentSyncInterval();
    config.isBackground = !isForeground;
    const newValue = rs.getCurrentSyncInterval();
    rs._emit('sync-interval-change', {oldValue: oldValue, newValue: newValue});
  }
  env.on('background', () => handleChange(false));
  env.on('foreground', () => handleChange(true));
}

/**
 * This class basically does six things:
 *
 * - retrieve the remote version of relevant documents and folders
 * - add all local and remote documents together into one tree
 * - push local documents out if they don't exist remotely
 * - push local changes out to remote documents (conditionally, to avoid race
 *   conditions where both have changed)
 * - adopt the local version of a document to its remote version if both exist
 *   and they differ
 * - delete the local version of a document if it was deleted remotely
 * - if any GET requests were waiting for remote data, resolve them once this
 *   data comes in.
 *
 * It does this using requests to documents and folders. Whenever a folder GET
 * comes in, it gives information about all the documents it contains (this is
 * the `markChildren` function).
 */
export class Sync {
  rs: RemoteStorage;

  /**
   * The local storage adapter this sync instance was created for. Storage
   * operations and change events are bound to it, so a response that arrives
   * after the session has been replaced cannot write into (or emit changes
   * through) the replacement session's adapter.
   */
  _sessionLocal: RemoteStorage["local"];

  /**
   * Maximum number of parallel requests to execute
   */
  numThreads: number = 10;

  /**
   * Sync done? `false` when periodic sync is currently running
   */
  done: boolean;

  /**
   * Sync stopped entirely
   */
  stopped: boolean;

  /**
   * Paths queued for sync, sometimes with callbacks. A callback may be
   * invoked with an error to settle a request that can no longer be
   * fulfilled (e.g. after the session has ended).
   */
  _tasks: { [key: string]: Array<(err?: Error) => void>; } = {};

  /**
   * Promises of currently running sync tasks per path
   */
  _running: { [key: string]: Promise<SyncTask | void>; } = {};

  /**
   * Start times of current sync per path
   */
  _timeStarted: { [key: string]: number; } = {};

  /**
   * Holds finished tasks for orderly processing
   */
  _finishedTasks: SyncTask[] = [];

  /** Remote invalidations not yet covered by a request. @internal */
  private remoteChanges = new Set<string>();
  private writeLeases = new Set<WriteLease>();
  private reportedWrites = new Set<string>();

  private destination(): string | undefined {
    const identity = this.rs.remote.getStorageIdentity?.();
    return identity ? JSON.stringify([this.rs.backend || 'remotestorage', identity]) : undefined;
  }

  private writeKey(node: RSNode): string {
    return node.push?.operation?.id || 'legacy:' + node.path + ':' + node.push?.timestamp;
  }

  private parkedWrite(node: RSNode): boolean {
    return !!node?.push && this.reportedWrites.has(this.writeKey(node));
  }

  private reportInterruptedWrite(node: RSNode): Error {
    const key = this.writeKey(node);
    const error = Object.assign(new SyncError('A pending local change needs review before syncing can continue.'), {
      path: node.path, operationId: node.push?.operation?.id, code: 'interrupted-write'
    });
    if (!this.reportedWrites.has(key)) {
      this.reportedWrites.add(key);
      const operation = node.push?.operation;
      if (operation?.state === 'conflict' && operation.observed) {
        const candidate = node.local || node.push;
        const change = { origin: 'conflict', path: node.path,
          oldValue: candidate.body, oldContentType: candidate.contentType,
          newValue: operation.observed.body === false ? undefined : operation.observed.body,
          newContentType: operation.observed.contentType,
          lastCommonValue: operation.base.body, lastCommonContentType: operation.base.contentType };
        setTimeout(() => { if (this.isCurrentSession()) { this._sessionLocal.emitChange(change); } }, 10);
      }
      this.rs._emit('error', error);
    }
    return error;
  }

  /** Raw retained candidates for an application recovery/export interface. */
  async listInterruptedWrites(): Promise<RSNode[]> {
    const nodes = [];
    await this._sessionLocal.forAllNodes((node: RSNode) => {
      if (node.push && this.rs.access.checkPathPermission(node.path, 'r')) { nodes.push(deepClone(node)); }
    });
    return nodes;
  }

  private sameRepresentation(left: RSItem, right: RSItem): boolean {
    if (left.body === false || right.body === false) { return left.body === false && right.body === false; }
    return left.body !== undefined && right.body !== undefined && equal(left.body, right.body) &&
      equalContentTypes(left.contentType, right.contentType);
  }

  /** Recheck an interrupted operation without blindly replaying its mutation.
   * Exact candidate readback confirms it; an unchanged base permits only a
   * conditional retry. Other versions remain retained for explicit resolution.
   */
  async retryInterruptedWrite(path: string, operationId: string): Promise<void> {
    if (!this.rs.access.checkPathPermission(path, 'rw')) { throw new Error('Write recovery is not permitted for this scope.'); }
    const lease = await acquireWriteLease(this._sessionLocal.sharedCacheId, this.destination(), path);
    if (lease) { this.writeLeases.add(lease); }
    try {
      if (!lease) { throw new Error('Write ownership cannot be established. Export the retained local changes.'); }
      await withCacheTransaction(this._sessionLocal, async () => {
        const nodes = await this._sessionLocal.getNodes([path]), node = nodes[path], operation = node?.push?.operation;
        this.assertCurrentSession();
        if (!operation || operation.id !== operationId || operation.version !== 1 || !operation.owned || operation.destination !== this.destination()) {
          throw new Error('This recovery selection is no longer current.');
        }
        operation.state = 'interrupted';
        await this._sessionLocal.setNodes(nodes);
        this.reportedWrites.delete(operationId);
      });
      const response = await this.rs.remote.get(path);
      if (![200, 404].includes(response.statusCode)) { throw new SyncError('The remote version could not be refreshed for recovery.'); }
      await withCacheTransaction(this._sessionLocal, async () => {
        const node = (await this._sessionLocal.getNodes([path]))[path];
        this.assertCurrentSession();
        if (node?.push?.operation?.id !== operationId || node.push.operation.destination !== this.destination()) {
          throw new Error('This recovery selection is no longer current.');
        }
        await this.recoverPush(path, operationId, response);
      });
    } finally { if (lease) { lease.release(); this.writeLeases.delete(lease); } }
    this.addTask(path);
    if (!this.stopped) { this.doTasks(); }
  }

  /** Explicit application decision after inspecting retained conflict versions.
   * Refreshes the reviewed remote version before dropping or replacing either
   * candidate. A further change requires another review instead of overwriting.
   */
  async resolveInterruptedWrite(path: string, operationId: string, choice: 'local' | 'remote'): Promise<void> {
    if (!['local', 'remote'].includes(choice) || !this.rs.access.checkPathPermission(path, 'rw')) {
      throw new Error('This write recovery decision is not permitted.');
    }
    const snapshot = await withCacheTransaction(this._sessionLocal, async () => {
      const node = (await this._sessionLocal.getNodes([path]))[path];
      this.assertCurrentSession();
      if (node?.push?.operation?.id !== operationId || node.push.operation.version !== 1 || node.push.operation.state !== 'conflict' || !node.push.operation.observed ||
            node.push.operation.destination !== this.destination() || !node.push.operation.owned) {
        throw new Error('This recovery selection is no longer current.');
      }
      return deepClone(node);
    });
    const lease = await acquireWriteLease(this._sessionLocal.sharedCacheId, this.destination(), path);
    if (lease) { this.writeLeases.add(lease); }
    try {
      if (!lease) { throw new Error('Write ownership cannot be established. Export the retained local changes.'); }
      await withCacheTransaction(this._sessionLocal, async () => {
        const node = (await this._sessionLocal.getNodes([path]))[path];
        this.assertCurrentSession();
        if (node?.push?.operation?.id !== operationId || node.push.operation.destination !== this.destination()) {
          throw new Error('This recovery selection is no longer current.');
        }
        if (!equal(node.local, snapshot.local) || !equal(node.push, snapshot.push)) {
          this.reportedWrites.delete(operationId);
          throw this.reportInterruptedWrite(node);
        }
      });
      const response = await this.rs.remote.get(path);
      if (![200, 404].includes(response.statusCode)) { throw new SyncError('The remote version could not be refreshed for review.'); }
      const observed: RSItem = { body: response.statusCode === 404 ? false : response.body,
        contentType: response.contentType, revision: response.revision, timestamp: this.now() };
      await withCacheTransaction(this._sessionLocal, async () => {
        const nodes = await this._sessionLocal.getNodes([path]), node = nodes[path];
        this.assertCurrentSession();
        if (node?.push?.operation?.id !== operationId || node.push.operation.destination !== this.destination()) { throw new Error('This recovery selection is no longer current.'); }
        const reviewed = snapshot.push.operation.observed;
        if (!equal(node.local, snapshot.local) || observed.revision !== reviewed.revision ||
            !this.sameRepresentation(observed, reviewed) || (choice === 'local' &&
              ((observed.body !== false && !observed.revision) || (observed.body === false && this.rs.remote.supportsAtomicCreate !== true)))) {
          node.push.operation.observed = observed;
          await this._sessionLocal.setNodes(nodes);
          this.reportedWrites.delete(operationId);
          throw this.reportInterruptedWrite(node);
        }
        if (choice === 'remote') { delete node.local; }
        else if (!node.local) { node.local = deepClone(node.push); delete (node.local as RSNode['push']).operation; }
        node.common = observed.body === false ? {} : observed;
        delete node.push; delete node.remote;
        if (choice === 'remote' && observed.body === false) { nodes[path] = undefined; }
        await this._sessionLocal.setNodes(nodes);
        this.reportedWrites.delete(operationId);
      });
    } finally { if (lease) { lease.release(); this.writeLeases.delete(lease); } }
    this.addTask(path);
    if (!this.stopped) { this.doTasks(); }
  }

  /** Reconcile an uncertain outcome only after fresh, unconditional readback. */
  private async recoverPush(path: string, operationId: string, response: RemoteResponse): Promise<void> {
    const nodes = await this._sessionLocal.getNodes([path]);
    this.assertCurrentSession();
    const node = nodes[path], push = node?.push, operation = push?.operation;
    if (!operation || operation.id !== operationId || operation.destination !== this.destination()) { return; }
    const observed: RSItem = { body: response.statusCode === 404 ? false : response.body,
      contentType: response.contentType, revision: response.revision, timestamp: this.now() };
    if (this.sameRepresentation(push, observed)) {
      node.common = observed.body === false ? {} : observed;
      if (node.local && this.sameRepresentation(node.local, push)) { delete node.local; }
      delete node.push; delete node.remote;
      if (observed.body === false && !node.local) { nodes[path] = undefined; }
      this.reportedWrites.delete(operationId);
    } else {
      const base = operation.base;
      const sameKnownRevision = !!base.revision && base.revision === observed.revision &&
        (base.body === undefined || this.sameRepresentation(base, observed));
      const sameUnversionedBase = !base.revision && this.sameRepresentation(base, observed);
      const stillAbsent = !base.revision && (base.body === undefined || base.body === false) && observed.body === false;
      if ((sameKnownRevision || sameUnversionedBase || stillAbsent) &&
          (observed.body !== false || this.rs.remote.supportsAtomicCreate === true) &&
          (observed.body === false || !!observed.revision) &&
          (this.rs.remote as typeof this.rs.remote & { supportsRevs?: boolean }).supportsRevs !== false && this.rs.access.checkPathPermission(path, 'rw')) {
        // The operation's captured base is still current. A subsequent task
        // creates a fresh operation guarded by this reviewed validator (or *).
        node.common = observed.body === false ? {} : observed;
        if (!node.local) { node.local = deepClone(push); delete (node.local as RSNode['push']).operation; }
        delete node.push; delete node.remote;
        this.reportedWrites.delete(operationId);
      } else {
        operation.state = 'conflict'; operation.observed = observed;
        await this._sessionLocal.setNodes(nodes);
        throw this.reportInterruptedWrite(node);
      }
    }
    await this._sessionLocal.setNodes(this.flush(nodes));
  }

  /** Queue a targeted revalidation, including when a request is in flight. @internal */
  refreshRemote (path: string): void {
    if (!this.rs.access.checkPathPermission(path, 'r')) { return; }
    this.remoteChanges.add(path);
    this.addTask(path);
    if (!this.stopped) { this.doTasks(); }
  }

  constructor (remoteStorage: RemoteStorage) {
    this.rs = remoteStorage;
    this._sessionLocal = remoteStorage.local;

    this._sessionLocal.onDiff(path => {
      this.addTask(path);
      this.doTasks();
    });

    this.rs.caching.onActivate((path: string): void => {
      this.addTask(path);
      this.doTasks();
    });

    this.addEvents(['done', 'req-done']);
  }

  /**
   * Return current time
   */
  now (): number {
    return new Date().getTime();
  }

  /**
   * Whether this `Sync` instance is still the active one for its
   * `RemoteStorage` session, i.e. responses it processes may still be applied.
   */
  isCurrentSession (): boolean {
    return this.rs.sync === this;
  }

  /**
   * Throw if this `Sync` instance is no longer the active one. Called after
   * asynchronous boundaries and before cache writes or change events, so a
   * response from a torn-down session is discarded instead of being applied to
   * the replacement session.
   */
  assertCurrentSession (): void {
    if (!this.isCurrentSession()) {
      throw new SessionEndedError();
    }
  }

  /**
   * When getting a path from the caching layer, this function might be handed
   * in to first check if it was updated on the remote, in order to fulfill a
   * maxAge requirement
   */
  async queueGetRequest (path: string): Promise<QueuedRequestResponse> {
    return new Promise((resolve, reject) => {
      if (!this.rs.remote.connected) {
        reject('cannot fulfill maxAge requirement - remote is not connected');
      } else if (!this.rs.remote.online) {
        reject('cannot fulfill maxAge requirement - remote is not online');
      } else {
        this.addTask(path, function (err?: Error): void {
          if (err) {
            reject(err);
          } else {
            this._sessionLocal.get(path).then(r => resolve(r));
          }
        }.bind(this));

        this.doTasks();
      }
    });
  }

  corruptServerItemsMap (itemsMap): boolean {
    if ((typeof(itemsMap) !== 'object') || (Array.isArray(itemsMap))) {
      return true;
    }

    for (const itemName in itemsMap) {
      const item = itemsMap[itemName];

      if (typeof(item) !== 'object') {
        return true;
      }
      if (typeof(item.ETag) !== 'string') {
        return true;
      }
      if (isFolder(itemName)) {
        if (itemName.substring(0, itemName.length-1).indexOf('/') !== -1) {
          return true;
        }
      } else {
        if (itemName.indexOf('/') !== -1) {
          return true;
        }
      }
    }

    return false;
  }

  corruptItemsMap (itemsMap): boolean {
    if ((typeof(itemsMap) !== 'object') || (Array.isArray(itemsMap))) {
      return true;
    }

    for (const path in itemsMap) {
      if (typeof itemsMap[path] !== 'boolean') {
        return true;
      }
    }

    return false;
  }

  corruptRevision (rev): boolean {
    return ((typeof(rev) !== 'object') ||
            (Array.isArray(rev)) ||
            (rev.revision && typeof(rev.revision) !== 'string') ||
            (rev.body && typeof(rev.body) !== 'string' && typeof(rev.body) !== 'object')  ||
            (rev.contentType && typeof(rev.contentType) !== 'string') ||
            (rev.contentLength && typeof(rev.contentLength) !== 'number') ||
            (rev.timestamp && typeof(rev.timestamp) !== 'number') ||
            (rev.itemsMap && this.corruptItemsMap(rev.itemsMap)));
  }

  isCorrupt (node: RSNode): boolean {
    return ((typeof(node) !== 'object') ||
            (Array.isArray(node)) ||
            (typeof(node.path) !== 'string') ||
            (this.corruptRevision(node.common)) ||
            (node.local && this.corruptRevision(node.local)) ||
            (node.remote && this.corruptRevision(node.remote)) ||
            (node.push && this.corruptRevision(node.push)));
  }

  hasTasks (): boolean {
    return Object.keys(this._tasks).length > 0;
  }

  /**
   * Collect sync tasks for changed nodes
   */
  async collectDiffTasks (): Promise<number> {
    let num = 0;

    return this._sessionLocal.forAllNodes((node: RSNode) => {
      if (num > 100) { return; }

      if (this.parkedWrite(node)) { return; }
      if (typeof node?.path === 'string' && node.push && isDocument(node.path) && this.rs.access.checkPathPermission(node.path, 'rw')) {
        this.addTask(node.path); num++; return;
      }

      if (this.isCorrupt(node)) {
        log('[Sync] WARNING: corrupt node in local cache', node);
        if (typeof(node) === 'object' && node.path) {
          this.addTask(node.path);
          num++;
        }
      } else if (this.needsFetch(node) &&
                 this.rs.access.checkPathPermission(node.path, 'r')) {
        this.addTask(node.path);
        num++;
      } else if (isDocument(node.path) && this.needsPush(node) &&
                 this.rs.access.checkPathPermission(node.path, 'rw')) {
        this.addTask(node.path);
        num++;
      }
    })
    .then((): number => num);
  }

  inConflict (node: RSNode): boolean {
    return (!!node.local && !!node.remote &&
            (node.remote.body !== undefined || !!node.remote.itemsMap));
  }

  needsRefresh (node: RSNode): boolean {
    if (node.common) {
      if (!node.common.timestamp) {
        return true;
      }
      return (this.now() - node.common.timestamp > Math.max(config.syncInterval, this.rs.remote.minRefreshInterval || 0));
    }
    return false;
  }

  needsFetch (node: RSNode): boolean {
    if (this.inConflict(node)) {
      return true;
    }
    if (node.common &&
        node.common.itemsMap === undefined &&
        node.common.body === undefined) {
      return true;
    }
    if (node.remote &&
        node.remote.itemsMap === undefined &&
        node.remote.body === undefined) {
      return true;
    }
    return false;
  }

  needsPush (node: RSNode): boolean {
    if (this.inConflict(node)) {
      return false;
    }
    if (node.local && !node.push) {
      return true;
    }
  }

  needsRemotePut (node: RSNode): boolean {
    return !!(node.local && node.local.body !== undefined && node.local.body !== false);
  }

  needsRemoteDelete (node: RSNode): boolean {
    return node.local && node.local.body === false;
  }

  getParentPath (path: string): string {
    const parts = path.match(/^(.*\/)([^\/]+\/?)$/);

    if (parts) {
      return parts[1];
    } else {
      throw new Error('Not a valid path: "'+path+'"');
    }
  }

  deleteChildPathsFromTasks (): void {
    if (this.rs.remote.folderETagsAreRecursive === false) { return; }
    for (const path in this._tasks) {
      if (this.remoteChanges.has(path)) { continue; }
      const paths = pathsFromRoot(path);

      for (let i=1; i < paths.length; i++) {
        if (this._tasks[paths[i]]) {
          // move pending promises to parent task
          if (Array.isArray(this._tasks[path]) && this._tasks[path].length) {
            Array.prototype.push.apply(
              this._tasks[paths[i]],
              this._tasks[path]
            );
          }
          delete this._tasks[path];
        }
      }
    }
  }

  /**
   * Collect tasks to refresh highest outdated folder in tree
   */
  async collectRefreshTasks (): Promise<void> {
    const cachedFolders = new Set<string>();
    if (this.rs.remote.folderETagsAreRecursive === false) {
      await this._sessionLocal.forAllNodes((node: RSNode) => {
        if (isFolder(node.path) && this.rs.access.checkPathPermission(node.path, 'r') &&
            this.rs.caching.checkPath(node.path) !== 'FLUSH') { cachedFolders.add(node.path); }
      });
    }
    await this._sessionLocal.forAllNodes((node: RSNode) => {
      let parentPath: string;
      if (this.needsRefresh(node)) {
        // Check every cached container: its own validator does not cover its
        // descendants. Child HEAD metadata then selects changed files to fetch,
        // avoiding an additional routine GET for every file in the same folder.
        if (this.rs.remote.folderETagsAreRecursive === false) {
          if (!isFolder(node.path) && (cachedFolders.has(this.getParentPath(node.path)) ||
              this.rs.remote.hasActiveSubscription?.(node.path))) { return; }
          if (this.rs.access.checkPathPermission(node.path, 'r')) { this.addTask(node.path); }
          return;
        }
        try {
          parentPath = this.getParentPath(node.path);
        } catch(e) {
          // node.path is already '/', can't take parentPath
        }
        if (parentPath && this.rs.access.checkPathPermission(parentPath, 'r')) {
          this.addTask(parentPath);
        } else if (this.rs.access.checkPathPermission(node.path, 'r')) {
          this.addTask(node.path);
        }
      }
    });

    this.deleteChildPathsFromTasks();
  }

  /**
   * Flush nodes from cache after sync to remote
   */
  flush (nodes: RSNodes): RSNodes {
    for (const path in nodes) {
      // Strategy is 'FLUSH' and no local changes exist
      if (this.rs.caching.checkPath(path) === 'FLUSH' &&
          nodes[path] && !nodes[path].local && !nodes[path].push) {
        log('[Sync] Flushing', path);
        nodes[path] = undefined; // Cause node to be flushed from cache
      }
    }
    return nodes;
  }

  /**
   * Sync one path
   */
  async doTask (path: string): Promise<SyncTask> {
    const lease = await acquireWriteLease(this._sessionLocal.sharedCacheId, this.destination(), path);
    if (lease) { this.writeLeases.add(lease); }
    const releaseLease = () => { if (lease) { lease.release(); this.writeLeases.delete(lease); } };
    try {
      this.assertCurrentSession();
      const task = await this.taskUnderLease(path, !!lease);
      task.releaseLease = releaseLease;
      return task;
    } catch (error) {
      releaseLease();
      throw error;
    }
  }

  private async taskUnderLease(path: string, owned: boolean): Promise<SyncTask> {
    const revalidate = this.remoteChanges.delete(path);
    return withCacheTransaction(this._sessionLocal, () => this._sessionLocal.getNodes([path]).then(async (nodes: RSNodes) => {
      // The session may have been replaced while the cache lookup was in
      // flight; do not act on it against the replacement session.
      this.assertCurrentSession();

      const node = nodes[path];
      if (node?.push) {
        const operation = node.push.operation;
        if (!owned || !operation?.owned || operation.version !== 1 || !operation.base || operation.destination !== this.destination() || operation.state === 'conflict') {
          throw this.reportInterruptedWrite(node);
        }
        if (!node.local) {
          node.local = deepClone(node.push);
          delete (node.local as RSNode['push']).operation;
        }
        operation.state = 'interrupted';
        await this._sessionLocal.setNodes(nodes);
        const task = taskFor('get', path, this.rs.remote.get(path));
        task.operationId = operation.id; task.recovering = true;
        return task;
      }
      if (revalidate) {
        return taskFor('get', path, this.rs.remote.get(path,
          node?.common?.revision ? { ifNoneMatch: node.common.revision } : {}));
      }
      // First fetch:
      if (typeof(node) === 'undefined') {
        return taskFor('get', path, this.rs.remote.get(path));
      }
      // Fetch known-stale child:
      else if (isStaleChild(node)) {
        return taskFor('get', path, this.rs.remote.get(path));
      }
      // A successful write can omit its ETag. Before another mutation, fetch
      // and compare the acknowledged representation instead of treating an
      // existing document as a create or attaching a later unrelated validator.
      else if (!hasCommonRevision(node) && node.common?.body !== undefined &&
               node.common.body !== false &&
               (this.needsRemotePut(node) || this.needsRemoteDelete(node))) {
        return taskFor('get', path, this.rs.remote.get(path));
      }
      // Push PUT:
      else if (this.needsRemotePut(node)) {
        node.push = deepClone(node.local);
        node.push.timestamp = this.now();
        node.push.operation = { version: 1, id: nextOperationId(), destination: this.destination(), base: deepClone(node.common || {}), owned, state: 'pending' };

        return this._sessionLocal.setNodes(this.flush(nodes)).then(() => {
          this.assertCurrentSession();

          let options;
          if (hasCommonRevision(node)) {
            options = { ifMatch: node.common.revision };
          } else {
            // Initial PUT (fail if something is already there)
            options = { ifNoneMatch: '*' };
          }

          const task = taskFor('put', path,
            this.rs.remote.put(
              path,
              node.push.body as XMLHttpRequestBodyInit,
              node.push.contentType,
              options
            )
          );
          task.operationId = node.push.operation.id;
          return task;
        });
      }
      // Push DELETE:
      else if (this.needsRemoteDelete(node)) {
        if (!hasCommonRevision(node)) { return taskFor('get', path, this.rs.remote.get(path)); }
        node.push = { body: false, timestamp: this.now() };
        node.push.operation = { version: 1, id: nextOperationId(), destination: this.destination(), base: deepClone(node.common || {}), owned, state: 'pending' };

        return this._sessionLocal.setNodes(this.flush(nodes)).then(() => {
          this.assertCurrentSession();

          if (hasCommonRevision(node)) {
            const task = taskFor('delete', path,
              this.rs.remote.delete(path, { ifMatch: node.common.revision })
            );
            task.operationId = node.push.operation.id;
            return task;
          } else { // Ascertain current common or remote revision first
            return taskFor('get', path, this.rs.remote.get(path));
          }
        });
      }
      // Conditional refresh:
      else if (hasCommonRevision(node)) {
        return taskFor('get', path,
          this.rs.remote.get(path, { ifNoneMatch: node.common.revision })
        );
      }
      else {
        return taskFor('get', path, this.rs.remote.get(path));
      }
    }));
  }

  /**
   * Merge/process folder node items after updates from remote
   */
  autoMergeFolder (node: RSNode): RSNode {
    if (node.remote.itemsMap) {
      node.common = node.remote;
      delete node.remote;

      if (node.common.itemsMap) {
        for (const itemName in node.common.itemsMap) {
          if (!node.local.itemsMap[itemName]) {
            // Indicates the node is either newly being fetched, or
            // has been deleted locally (whether or not leading to
            // conflict); before listing it in local listings, check
            // if a local deletion exists.
            node.local.itemsMap[itemName] = false;
          }
        }

        for (const itemName in node.local.itemsMap) {
          if (!node.common.itemsMap[itemName]) {
            // When an item appears in a folder's local itemsMap, but
            // not in remote/common, it may or may not have been
            // changed or deleted locally. The local itemsMap may
            // only contain it, beause the item existed when
            // *another* local item was changed, so we need to make
            // sure that it's checked/processed again, so it will be
            // deleted if there's no local change waiting to be
            // pushed out.
            this.addTask(node.path+itemName);
          }
        }

        if (equal(node.local.itemsMap, node.common.itemsMap)) {
          delete node.local;
        }
      }
    }
    return node;
  }

  /**
   * Merge/process document node items after updates from remote
   */
  autoMergeDocument (node: RSNode): RSNode {
    if (hasNoRemoteChanges(node)) {
      node = mergeMutualDeletion(node);
      // Only adopt a missing write validator when readback confirms that the
      // bytes and media type still equal the acknowledged common version.
      if (!node.common.revision && node.remote.revision &&
          node.common.body !== undefined && node.remote.body !== false) {
        node.common = node.remote;
      }
      delete node.remote;
    } else if (node.remote.body !== undefined) {
      if (node.remote.body === false && node.local?.body === false) {
        // Deleted on both sides, nothing to do
      } else {
        log('[Sync] Emitting conflict event');
        // Capture the values now, before `node.local`/`node.remote` are
        // deleted below.
        const change = {
          origin:          'conflict',
          path:            node.path,
          oldValue:        node.local.body,
          newValue:        node.remote.body,
          lastCommonValue: node.common.body,
          oldContentType:  node.local.contentType,
          newContentType:  node.remote.contentType,
          lastCommonContentType: node.common.contentType
        };
        const sessionLocal = this._sessionLocal;
        setTimeout(() => {
          // The session may have been replaced during the delay. The conflict
          // belongs to the old session and must not be emitted through the
          // replacement session's adapter.
          if (this.isCurrentSession()) {
            sessionLocal.emitChange(change);
          }
        }, 10);
      }

      if (node.remote.body === false) {
        node.common = {};
      } else {
        node.common = node.remote;
      }
      delete node.remote;
      delete node.local;
    }

    return node;
  }

  /**
   * Merge/process node items after various updates from remote
   */
  autoMerge (node: RSNode): RSNode {
    // Guard all change events emitted below: if the session has been replaced,
    // the merge result belongs to the old session and must be dropped.
    this.assertCurrentSession();

    // Neither a live write nor an uncertain persisted write may lose its local
    // candidate to a racing refresh. Matching acknowledgement/readback owns
    // reconciliation; parent listings retain only an invalidation meanwhile.
    if (isDocument(node.path) && node.push) { return node; }

    if (!node.remote) {
      if (node.common.body !== undefined && node.common.body !== false) {
        this._sessionLocal.emitChange({
          origin:   'remote',
          path:     node.path,
          oldValue: node.common.body,
          newValue: undefined,
          oldContentType: node.common.contentType,
          newContentType: undefined
        });
      }
      return;
    }

    // Local changes
    if (node.local) {
      if (isFolder(node.path)) {
        return this.autoMergeFolder(node);
      } else {
        return this.autoMergeDocument(node);
      }
    }

    if (isFolder(node.path)) {
      if (node.remote.itemsMap !== undefined) {
        node.common = node.remote;
        delete node.remote;
      }
    } else {
      if (node.remote.body !== undefined) {
        const change = {
          origin:   'remote',
          path:     node.path,
          oldValue: (node.common.body === false ? undefined : node.common.body),
          newValue: (node.remote.body === false ? undefined : node.remote.body),
          oldContentType: node.common.contentType,
          newContentType: node.remote.contentType
        };

        if (change.oldValue !== undefined || change.newValue !== undefined) {
          this._sessionLocal.emitChange(change);
        }

        if (node.remote.body === false) {
          return; // no remote, so delete
        }

        node.common = node.remote;
        delete node.remote;
      }
    }

    return node;
  }

  async updateCommonTimestamp (path: string, revision: string): Promise<void> {
    return this._sessionLocal.getNodes([path]).then((nodes: RSNodes) => {
      this.assertCurrentSession();

      if (nodes[path] &&
          nodes[path].common &&
          nodes[path].common.revision === revision) {
        nodes[path].common.timestamp = this.now();
      }
      return this._sessionLocal.setNodes(this.flush(nodes));
    });
  }

  /**
   * After successful GET of a folder, mark its children/items for
   * changes and further processing
   */
  async markChildren (path: string, itemsMap: RSItem["itemsMap"], changedNodes: RSNodes, missingChildren: { [key: string]: boolean }): Promise<void> {
    const paths = [];
    const meta = {};
    const recurse = {};

    for (const item in itemsMap) {
      paths.push(path+item);
      meta[path+item] = itemsMap[item];
    }
    for (const childName in missingChildren) {
      paths.push(path+childName);
    }

    const nodes = await this._sessionLocal.getNodes(paths);
    this.assertCurrentSession();

    let cachingStrategy;
    let node;

    for (const nodePath in nodes) {
      node = nodes[nodePath];

      if (meta[nodePath]) {
        if (node && node.common) {
          if (nodeChanged(node, meta[nodePath].ETag)) {
            changedNodes[nodePath] = deepClone(node);
            changedNodes[nodePath].remote = {
              revision:  meta[nodePath].ETag,
              timestamp: this.now()
            };
            changedNodes[nodePath] = this.autoMerge(changedNodes[nodePath]);
          }
        } else {
          cachingStrategy = this.rs.caching.checkPath(nodePath);
          if (cachingStrategy === 'ALL') {
            changedNodes[nodePath] = {
              path: nodePath,
              common: {
                timestamp: this.now()
              },
              remote: {
                revision: meta[nodePath].ETag,
                timestamp: this.now()
              }
            };
          }
        }

        if (changedNodes[nodePath] && meta[nodePath]['Content-Type']) {
          changedNodes[nodePath].remote.contentType = meta[nodePath]['Content-Type'];
        }

        if (changedNodes[nodePath] && meta[nodePath]['Content-Length']) {
          changedNodes[nodePath].remote.contentLength = meta[nodePath]['Content-Length'];
        }
      } else if (missingChildren[nodePath.substring(path.length)] && node && node.common) {
        if (node.common.itemsMap) {
          for (const commonItem in node.common.itemsMap) {
            recurse[nodePath+commonItem] = true;
          }
        }

        if (node.local && node.local.itemsMap) {
          for (const localItem in node.local.itemsMap) {
            recurse[nodePath+localItem] = true;
          }
        }

        if (node.remote || isFolder(nodePath)) {
          changedNodes[nodePath] = undefined;
        } else {
          changedNodes[nodePath] = this.autoMerge(node);

          if (typeof changedNodes[nodePath] === 'undefined') {
            const parentPath = this.getParentPath(nodePath);
            const parentNode = changedNodes[parentPath];
            const itemName = nodePath.substring(path.length);
            if (parentNode && parentNode.local) {
              delete parentNode.local.itemsMap[itemName];

              if (equal(parentNode.local.itemsMap, parentNode.common.itemsMap)) {
                delete parentNode.local;
              }
            }
          }
        }
      }
    }

    const changedNodes2 = await this.markRemoteDeletions(Object.keys(recurse), changedNodes);
    if (changedNodes2) {
      this.assertCurrentSession();
      await this._sessionLocal.setNodes(this.flush(changedNodes2));
    }
  }

  /**
   * Recursively process paths to mark documents as remotely deleted
   * where applicable
   */
  async markRemoteDeletions (paths: string[], changedNodes: RSNodes): Promise<RSNodes | void> {
    if (paths.length === 0) { return changedNodes; }

    const nodes = await this._sessionLocal.getNodes(paths);
    this.assertCurrentSession();

    const subPaths = {};

    function collectSubPaths (folder: RSItem, path: string): void {
      if (folder && folder.itemsMap) {
        for (const itemName in folder.itemsMap) {
          subPaths[path+itemName] = true;
        }
      }
    }

    for (const path in nodes) {
      const node = nodes[path];
      if (!node) { continue; }

      if (isFolder(path)) {
        collectSubPaths(node.common, path);
        collectSubPaths(node.local, path);
      } else {
        if (node.common && typeof(node.common.body) !== 'undefined') {
          changedNodes[path] = deepClone(node);
          changedNodes[path].remote = {
            body:      false,
            timestamp: this.now()
          };
          changedNodes[path] = this.autoMerge(changedNodes[path]);
        }
      }
    }

    // Recurse whole tree depth levels at once:
    const changedNodes2 = await this.markRemoteDeletions(Object.keys(subPaths), changedNodes);
    if (changedNodes2) {
      this.assertCurrentSession();
      await this._sessionLocal.setNodes(this.flush(changedNodes2));
    }
  }

  /**
   * Complete a successful GET request
   */
  async completeFetch (path: string, bodyOrItemsMap: RSItem["body"], contentType: string, revision: string): Promise<any> {
    let paths: string[];
    let parentPath: string;
    const pathsFromRootArr = pathsFromRoot(path);

    if (isFolder(path)) {
      paths = [path];
    } else {
      parentPath = pathsFromRootArr[1];
      paths = [path, parentPath];
    }

    const nodes = await this._sessionLocal.getNodes(paths);
    this.assertCurrentSession();

    const parentNode: RSNode = nodes[parentPath];
    const missingChildren = {};
    let node: RSNode = nodes[path];
    let itemName: string;

    function collectMissingChildren (folder): void {
      if (folder && folder.itemsMap) {
        for (itemName in folder.itemsMap) {
          if (!bodyOrItemsMap[itemName]) {
            missingChildren[itemName] = true;
          }
        }
      }
    }

    if (typeof(node) !== 'object' ||
        node.path !== path ||
        typeof(node.common) !== 'object') {
      node = { path: path, common: {} };
      nodes[path] = node;
    }

    node.remote = {
      revision: revision,
      timestamp: this.now()
    };

    if (isFolder(path)) {
      collectMissingChildren(node.common);
      collectMissingChildren(node.remote);

      node.remote.itemsMap = {};
      for (itemName in bodyOrItemsMap as RSItem["itemsMap"]) {
        node.remote.itemsMap[itemName] = true;
      }
    } else {
      node.remote.body = bodyOrItemsMap;
      node.remote.contentType = contentType;

      if (parentNode && parentNode.local && parentNode.local.itemsMap) {
        itemName = path.substring(parentPath.length);

        if (bodyOrItemsMap !== false) {
          parentNode.local.itemsMap[itemName] = true;
        } else {
          if (parentNode.local.itemsMap[itemName]) {
            // node is 404 on remote, can safely be removed from
            // parent's local itemsMap now
            delete parentNode.local.itemsMap[itemName];
          }
        }

        if (equal(parentNode.local.itemsMap, parentNode.common.itemsMap)) {
          delete parentNode.local;
        }
      }
    }

    nodes[path] = this.autoMerge(node);

    return { toBeSaved: nodes, missingChildren };
  }

  /**
   * Handle successful PUT or DELETE request
   */
  async completePush (path: string, action: "put" | "delete", conflict: boolean, revision: string, operationId?: string): Promise<void> {
    const nodes = await this._sessionLocal.getNodes([path]);
    this.assertCurrentSession();

    const node = nodes[path];

    if (operationId && node?.push?.operation?.id !== operationId) { return; }
    if (node?.push?.operation && node.push.operation.id !== operationId) { return; }

    if (!node.push) {
      this.stopped = true;
      throw new Error('completePush called but no push version!');
    }

    if (conflict) {
      if (node.push.operation) {
        node.push.operation.state = 'interrupted';
        await this._sessionLocal.setNodes(nodes);
        return;
      }
      log('[Sync] We have a conflict');

      if (!node.remote || node.remote.revision !== revision) {
        node.remote = {
          revision:  revision || 'conflict',
          timestamp: this.now()
        };
        delete node.push;
      }

      nodes[path] = this.autoMerge(node);
    } else {
      node.common = {
        revision:  revision,
        timestamp: this.now()
      };

      if (action === 'put') {
        node.common.body = node.push.body;
        node.common.contentType = node.push.contentType;

        if (node.local && equal(node.local.body, node.push.body) &&
            equalContentTypes(node.local.contentType, node.push.contentType)) {
          delete node.local;
        }

        delete node.push;
      } else if (action === 'delete') {
        if (!node.local || node.local.body === false) { // No new local changes since push; flush it.
          nodes[path] = undefined;
        } else {
          delete node.push;
        }
      }
    }

    if (!conflict && nodes[path]?.remote) {
      delete nodes[path].remote;
      this.remoteChanges.add(path);
    }

    this.assertCurrentSession();
    await this._sessionLocal.setNodes(this.flush(nodes));
  }

  /**
   * Remove push item from cached nodes that failed to sync
   */
  async dealWithFailure (path: string, operationId?: string): Promise<void> {
    const nodes = await this._sessionLocal.getNodes([path]);
    this.assertCurrentSession();

    if (operationId && nodes[path]?.push?.operation?.id === operationId) {
      nodes[path].push.operation.state = 'interrupted';
      return this._sessionLocal.setNodes(this.flush(nodes));
    }
  }

  interpretStatus (statusCode: string | number): ResponseStatus {
    const status: ResponseStatus = {
      statusCode:      statusCode,
      successful:      undefined,
      conflict:        undefined,
      unAuth:          undefined,
      notFound:        undefined,
      changed:         undefined,
      networkProblems: undefined
    };

    if (typeof statusCode === 'string' &&
        (statusCode === 'offline' || statusCode === 'timeout')) {
      status.successful = false;
      status.networkProblems = true;
      return status;
    } else if (typeof statusCode === 'number') {
      const series = Math.floor(statusCode / 100);

      status.successful = (series === 2 ||
                           statusCode === 304 ||
                           statusCode === 412 ||
                           statusCode === 404);
      status.conflict   = (statusCode === 412);
      status.unAuth     = ((statusCode === 401 && this.rs.remote.token !== Authorize.IMPLIED_FAKE_TOKEN) ||
                           statusCode === 402 ||
                           statusCode === 403);
      status.notFound   = (statusCode === 404);
      status.changed    = (statusCode !== 304);

      return status;
    }
  }

  /**
   * Handle successful GET request
   */
  async handleGetResponse (path: string, status: ResponseStatus, bodyOrItemsMap: RSItem["body"], contentType: string, revision: string): Promise<boolean> {
    if (status.notFound) {
      bodyOrItemsMap = isFolder(path) ? {} : false;
    }

    if (status.changed) {
      const data = await this.completeFetch(path, bodyOrItemsMap, contentType, revision);

      if (isFolder(path)) {
        if (this.corruptServerItemsMap(bodyOrItemsMap)) {
          log('[Sync] WARNING: Discarding corrupt folder description from server for ' + path);
          return false;
        }
        await this.markChildren(path, bodyOrItemsMap as RSItem["itemsMap"], data.toBeSaved, data.missingChildren);
      } else {
        this.assertCurrentSession();
        await this._sessionLocal.setNodes(this.flush(data.toBeSaved));
      }
    } else {
      await this.updateCommonTimestamp(path, revision);
    }
    return true;
  }

  /**
   * Handle response of executed request
   */
  async handleResponse (path: string, action: SyncTask["action"], r: RemoteResponse, operationId?: string, recovering: boolean = false): Promise<boolean> {
    this.assertCurrentSession();

    if (operationId) {
      const node = (await this._sessionLocal.getNodes([path]))[path];
      this.assertCurrentSession();
      if (node?.push?.operation?.id !== operationId || node.push.operation.destination !== this.destination()) { return true; }
    }

    const status = this.interpretStatus(r.statusCode);

    if (recovering && operationId && (r.statusCode === 200 || r.statusCode === 404)) {
      await this.recoverPush(path, operationId, r);
      return true;
    }

    if (status.successful) {
      if (action === 'get') {
        return this.handleGetResponse(path, status, r.body, r.contentType, r.revision);
      } else if (action === 'put' || action === 'delete') {
        return this.completePush(path, action, status.conflict, r.revision, operationId).then(function () {
          return true;
        });
      } else {
        throw new Error(`cannot handle response for unknown action ${action}`);
      }
    } else {
      // Unsuccessful
      let error: Error;
      if (status.unAuth) {
        error = new UnauthorizedError();
      } else if (status.networkProblems) {
        error = new SyncError('Network request failed.');
      } else {
        error = new Error('HTTP response code ' + status.statusCode + ' received.');
      }

      return this.dealWithFailure(path, operationId).then(() => {
        this.rs._emit('error', error);
        throw error;
      });
    }
  }

  /**
   * Mark a request promise as observed, so an abandoned task cannot surface as
   * an unhandled rejection. `finishTask()` normally surfaces failures to
   * queued callers, but tasks discarded after a session change are never
   * awaited.
   */
  observeAbandonedTask (promise: Promise<unknown>): void {
    promise.catch(() => {
      // Intentionally empty: only here to mark the rejection as observed.
    });
  }

  /**
   * Abandon this sync instance after its session has been replaced, so no
   * stale response can be written into the replacement session. Settles all
   * queued callbacks (including parked successors and tasks that were never
   * started) and drops all bookkeeping.
   */
  discardStaleTask (task: SyncTask): void {
    log('[Sync] discarding stale task after session change:', task.path);

    // Observe every outstanding request before dropping it, including the head
    // task and any successors parked in `_finishedTasks`, so a later rejection
    // cannot become an unhandled rejection.
    this.observeAbandonedTask(task.promise);
    for (const parked of this._finishedTasks) {
      this.observeAbandonedTask(parked.promise);
    }
    for (const path of Object.keys(this._running)) {
      this.observeAbandonedTask(this._running[path]);
    }

    this.failAllQueuedTasks(new Error(SESSION_ENDED_MESSAGE));
    this._running = {};
    this._timeStarted = {};
    this._finishedTasks = [];
    for (const lease of this.writeLeases) { lease.release(); }
    this.writeLeases.clear();
  }

  /**
   * Execute/finish running tasks, one at a time
   */
  async finishTask (task: SyncTask, queueTask: boolean = true): Promise<void> {
    // A task's response is awaited below, so the session may change (e.g. via
    // `disconnect()`) while this method is already in flight. Discard the task
    // both when it is picked up and again after its response arrives, so a
    // held GET/PUT/DELETE from a torn-down session is never applied to the
    // replacement adapter or emitted as change events.
    // `stopSync()` leaves `rs.sync` in place, so in-flight tasks still complete
    // normally in that case.
    if (!this.isCurrentSession()) {
      this.discardStaleTask(task);
      return;
    }

    if (task.action === undefined) {
      task.releaseLease?.();
      delete this._running[task.path];
      return;
    }

    if (queueTask) {
      log("[Sync] queue finished task:", task.path);
      this._finishedTasks.push(task);
      if (this._finishedTasks.length > 1) {
        log("[Sync] delaying finished task:", task.path);
        return;
      }
    }

    log("[Sync] run task:", task.path);

    let res;
    try {
      res = await task.promise;
    } catch (err) {
      log('[Sync] wire client rejects its promise', task.path, task.action, err);
      res = { statusCode: err instanceof UnauthorizedError ? 401 : 'offline' };
    }

    // Re-check after awaiting the response: the session may have been replaced
    // while the request was in flight.
    if (!this.isCurrentSession()) {
      this.discardStaleTask(task);
      return;
    }

    try {
      const completed = await withCacheTransaction(this._sessionLocal, () =>
        this.handleResponse(task.path, task.action, res, task.operationId, task.recovering));
      this.finishSuccessfulTask(task, completed);
    } catch (err) {
      // A `SessionEndedError` means the session changed after the check above
      // (e.g. while `handleResponse` awaited a cache read). The response was
      // not applied, so discard the task instead of reporting a failure.
      if (err instanceof SessionEndedError) {
        this.discardStaleTask(task);
        return;
      }
      this.finishUnsuccessfulTask(task, err);
    }
  }

  async finishSuccessfulTask (task: SyncTask, completed: boolean): Promise<void> {
    task.releaseLease?.();
    this._finishedTasks.shift();
    delete this._timeStarted[task.path];
    delete this._running[task.path];

    // An event arriving after doTask began must get a subsequent request.
    if (completed && !this.remoteChanges.has(task.path)) {
      if (this._tasks[task.path]) {
        for (let i=0; i < this._tasks[task.path].length; i++) {
          this._tasks[task.path][i]();
        }
        delete this._tasks[task.path];
      }
    }

    this.rs._emit('sync-req-done', {
      tasksRemaining: Object.keys(this._tasks).length
    });

    if (this._finishedTasks.length > 0) {
      await this.finishTask(this._finishedTasks[0], false);
      return;
    }

    await this.collectTasks(false).then(() => {
      // See if there are any more tasks that are not refresh tasks
      if (!this.hasTasks() || this.stopped) {
        if (!this.done) { this.done = true; }
        this.rs._emit('sync-done', { completed: true });
      } else {
        // Use a 10ms timeout to let the JavaScript runtime catch its breath
        // (and hopefully force an IndexedDB auto-commit?), and also to cause
        // the threads to get staggered and get a good spread over time:
        setTimeout(() => { this.doTasks(); }, 10);
      }
    });
  }

  async finishUnsuccessfulTask (task: SyncTask, err: Error): Promise<void> {
    task.releaseLease?.();
    if ((err as Error & { code?: string }).code === 'interrupted-write') { this.failQueuedTasks(task.path, err); }
    log('[Sync]', err.message);

    this._finishedTasks.shift();
    delete this._timeStarted[task.path];
    delete this._running[task.path];

    this.rs._emit('sync-req-done', {
      tasksRemaining: Object.keys(this._tasks).length
    });

    if (this._finishedTasks.length > 0) {
      await this.finishTask(this._finishedTasks[0], false);
      return;
    }

    if (!this.done) {
      this.done = true;
      this.rs._emit('sync-done', { completed: false });
    }
  }

  /**
   * Determine how many tasks we want to have
   */
  tasksWanted (): number {
    if (!this.rs.remote.connected) {
      // Nothing to sync if no remote connected
      return 0;
    }

    if (this.rs.remote.online) {
      // Run as many tasks as threads are available/configured
      return this.numThreads;
    } else {
      // Only run 1 task when we're offline
      return 1;
    }
  }

  /**
   * Check if more tasks can be queued, and start running
   * tasks
   *
   * @returns {Boolean} `true` when all tasks have been started or
   *                    there's nothing to do, `false` if we could
   *                    or want to run more
   */
  /**
   * Handle a task that failed before its response could be processed, e.g.
   * because a cache read rejected or the session ended while the task was
   * starting. Settles any queued callers and clears bookkeeping.
   */
  taskFailed (path: string, err: Error): void {
    if (err instanceof SessionEndedError) {
      this.failQueuedTasks(path, new Error(SESSION_ENDED_MESSAGE));
    } else {
      log('[Sync] task failed to start', path, err);
      this.failQueuedTasks(path, err);
    }
    delete this._running[path];
    delete this._timeStarted[path];
  }

  doTasks (): boolean {
    const numToHave = this.tasksWanted();
    const numToAdd = numToHave - Object.keys(this._running).length;
    if (numToAdd <= 0) { return true; }

    // `this.done` is `true` for immediate sync and `false` for
    // periodic sync
    if (this.hasTasks() && !this.done) {
      this.rs._emit('sync-started');
    }

    let numAdded: number = 0;

    for (const path in this._tasks) {
      if (!this._running[path]) {
        this._timeStarted[path] = this.now();
        this._running[path] = this.doTask(path)
          .then(this.finishTask.bind(this))
          .catch((err: Error) => { this.taskFailed(path, err); });
        numAdded++;
        if (numAdded >= numToAdd) { break; }
      }
    }

    return (numAdded >= numToAdd);
  }

  /**
   * Collect any potential sync tasks if none are queued
   */
  async collectTasks (alsoCheckRefresh: boolean = true): Promise<void> {
    if (this.hasTasks() || this.stopped) { return; }

    const numDiffs = await this.collectDiffTasks();
    if (numDiffs > 0) { return; }

    if (alsoCheckRefresh) {
      return this.collectRefreshTasks();
    }
  }

  /**
   * Add a sync task for the given path
   */

  addTask (path: string, cb?: (err?: Error) => void): void {
    if (!this._tasks[path]) {
      this._tasks[path] = [];
    }
    if (typeof(cb) === 'function') {
      this._tasks[path].push(cb);
    }
  }

  /**
   * Fail queued callbacks for a path, e.g. when the session ended before
   * their task could complete. Settles `queueGetRequest` promises that
   * would otherwise stay pending forever after `disconnect()`.
   */
  failQueuedTasks (path: string, err: Error): void {
    const callbacks = this._tasks[path];
    if (callbacks) {
      for (let i = 0; i < callbacks.length; i++) {
        callbacks[i](err);
      }
      delete this._tasks[path];
    }
  }

  /**
   * Fail every queued callback for this sync instance. Used when the session
   * is torn down, so `queueGetRequest` promises settle immediately instead of
   * waiting for a response that may never arrive.
   */
  failAllQueuedTasks (err: Error): void {
    for (const path of Object.keys(this._tasks)) {
      this.failQueuedTasks(path, err);
    }
  }

  /**
   * Start a sync procedure
   */
  public async sync (): Promise<void> {
    this.done = false;

    const remote = this.rs.remote;
    if (remote.connected && remote.prepareSync) {
      try {
        await remote.prepareSync();
      } catch (error) {
        if (this.isCurrentSession() && this.rs.remote === remote) {
          this.done = true;
          this.rs._emit('error', error instanceof UnauthorizedError ? error : new SyncError(error));
          this.rs._emit('sync-done', { completed: false });
        }
        return;
      }
      if (!this.isCurrentSession() || this.rs.remote !== remote) { return; }
    }

    if (!this.doTasks()) {
      try {
        await this.collectTasks();
      } catch (e) {
        log('[Sync] Sync error', e);
        throw new Error('Local cache unavailable');
      };

      this.doTasks();
      // All stale resources may be subscribed. Complete the idle cycle too,
      // so the next timer can poll resources whose subscription later fails.
      if (this.rs.backend === 'solid' && this.isCurrentSession() && !this.hasTasks() &&
          !Object.keys(this._running).length && !this.done) {
        this.done = true;
        this.rs._emit('sync-done', { completed: true });
      }
    }
  }

  static _rs_init (remoteStorage: RemoteStorage): void {
    setupSync = function (): void {
      // if (!config.cache) return false
      const env = new Env();
      if (env.isBrowser()) { handleVisibility(env, remoteStorage); }

      if (!remoteStorage.sync) {
        // Call this now that all other modules are also ready:
        remoteStorage.sync = new Sync(remoteStorage);

        if (remoteStorage.syncStopped) {
          log('[Sync] Initializing with sync stopped');
          remoteStorage.sync.stopped = true;
          delete remoteStorage.syncStopped;
        }
      }

      remoteStorage.setupSyncCycle();
    };

    syncOnConnect = function (): void {
      remoteStorage.removeEventListener('connected', syncOnConnect);
      remoteStorage.startSync();
    };

    remoteStorage.on('ready', setupSync);
    remoteStorage.on('connected', syncOnConnect);
  }

  static _rs_cleanup (remoteStorage: RemoteStorage): void {
    remoteStorage.stopSync();

    if (remoteStorage.sync) {
      // Settle pending requests now, rather than waiting for a response that
      // may never arrive after the session has been torn down.
      remoteStorage.sync.failAllQueuedTasks(new Error(SESSION_ENDED_MESSAGE));
      for (const lease of remoteStorage.sync.writeLeases) { lease.release(); }
      remoteStorage.sync.writeLeases.clear();
    }

    remoteStorage.removeEventListener('ready', setupSync);
    remoteStorage.removeEventListener('connected', syncOnConnect);
    remoteStorage.caching.resetActivationHandler();

    remoteStorage.sync = undefined;
    delete remoteStorage.sync;
  }
}

export interface Sync extends EventHandling {}
applyMixins(Sync, [EventHandling]);

export default Sync;
